def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The five-cell horizontal pattern at the top is the template.
    template = next(
        [grid[r][c:c + 5] for r in range(h) for c in range(w - 4)
         if all(grid[r][c + k] != 8 for k in range(5))]
    )

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                for k, value in enumerate(template):
                    cc = c + k - 2
                    if 0 <= cc < w:
                        out[r][cc] = value
    return out
